// Four numbers: given a list of up to four distinct integers between 1 and 10,
// find a list of three integers x1, x2, x3 between 1 and 10 such that every
// given number can be generated by summing a subset of x1, x2, x3.

fn build(inst: &Instance, m: &mut Model) -> Res<Out> {
    let numbers = inst.ints("numbers");

    // The three integers to find, each between 1 and 10.
    let mut x: Vec<View<i64>> = Vec::new();
    for _ in 0..3 {
        x.push(m.new_int_decision(1..=10));
    }

    // Each given number is the sum of some subset of x1, x2, x3.
    // Every subset is a choice: a Boolean picks it, and the picked subset sums to the number.
    for &v in numbers.iter() {
        let mut picks: Vec<View<bool>> = Vec::new();
        for mask in 1usize..8 {
            let members: Vec<View<i64>> = (0usize..3)
                .filter(|&i| (mask >> i) & 1 == 1)
                .map(|i| x[i])
                .collect();
            let b = m.new_bool_decision();
            m.linear(members.iter().copied().sum::<IntLinearExp>())
                .eq(v)
                .implied_by(b)
                .post()?;
            picks.push(b);
        }
        // At least one subset sums to the given number.
        m.linear(picks.iter().copied().sum::<IntLinearExp>())
            .ge(1)
            .post()?;
    }

    let mut out = Out::new();
    out.put("x", x);
    Ok(out)
}
